public class InnerGatewayTargetCredentialProviderFactory(Action<Humidifier.BedrockAgentCore.GatewayTargetTypes.CredentialProvider> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTargetTypes.CredentialProvider>
{

    internal InnerGatewayTargetOAuthCredentialProviderFactory OauthCredentialProviderFactory { get; set; }

    internal InnerGatewayTargetIamCredentialProviderFactory IamCredentialProviderFactory { get; set; }

    internal InnerGatewayTargetApiKeyCredentialProviderFactory ApiKeyCredentialProviderFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTargetTypes.CredentialProvider Create()
    {
        var credentialProviderResult = CreateCredentialProvider();
        factoryAction?.Invoke(credentialProviderResult);

        return credentialProviderResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTargetTypes.CredentialProvider CreateCredentialProvider()
    {
        var credentialProviderResult = new Humidifier.BedrockAgentCore.GatewayTargetTypes.CredentialProvider();

        return credentialProviderResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTargetTypes.CredentialProvider result)
    {
        base.CreateChildren(result);

        result.OauthCredentialProvider ??= OauthCredentialProviderFactory?.Build();
        result.IamCredentialProvider ??= IamCredentialProviderFactory?.Build();
        result.ApiKeyCredentialProvider ??= ApiKeyCredentialProviderFactory?.Build();
    }

} // End Of Class

